j:jelly.script:

	addAfterPageLoadedEvent(function() {
		var pageSize = 20;
		var columns = '';
		$j("#${jvar_name}").select2({
			placeholder: "${JS:jvar_placeholder}",
			multiple: true,
			ajax: {
				url: "data_table.do",
				dataType: "json",
				quietMillis: NOW.ac_wait_time,
				data: function(search, page) {
					return {
						sysparm_reference: "${JS:jvar_table}",
						sysparm_target: "",
						sysparm_query: "${JS:jvar_query}",
						sysparm_columns: "${JS:jvar_display_value}",
						iSortCol_0: "${JS:jvar_order_by}",
						iDisplayStart: ((page - 1) * pageSize) + "",
						iDisplayLength: pageSize,
						sSearch_0: search
					};
				},
				results: function(data, page) {
					var more = (page * pageSize) ${LT} data.iTotalRecords;
					return {results: data.aaData, more: more};
				}
			},
			formatResult: function(item) {
				return item.DT_RowId.substring(item.DT_RowId.indexOf(':') + 1);
			},
			formatSelection: function(item) {
				return item.DT_RowId.substring(item.DT_RowId.indexOf(':') + 1);
			},
			id: function(item) {
				return item.DT_RowId.split(":")[0];
			},
			initSelection : function (element, callback) {
        		    $j.ajax({
                		url:  "data_table.do",
                		type: "POST",
                		dataType: "json",
                		data:  {
					sysparm_reference: "${JS:jvar_table}",
					sysparm_target: "",
					sysparm_query: "sys_idIN" + $(element).val(),
					sysparm_columns: "${JS:jvar_display_value}",
					iSortCol_0: "${JS:jvar_order_by}",
                			iDisplayStart: "0",
                			iDisplayLength: 1000,
                			sSearch_0: null,
					paging: false
				}
			    }).done(function(data) {
					callback(data.aaData);
			    });
      			}
		});
		if ("${JS:jvar_onchange}") {
			$j("#${jvar_name}").on("change", function(e) { ${JS:jvar_onchange} });
		}
	});
